import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  label?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  defaultTags = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const unique: string[] = [];
    next.forEach((tag) => {
      const trimmed = tag.trim();
      if (trimmed && !unique.includes(trimmed)) unique.push(trimmed);
    });
    apply(unique);
  };

  const remove = (tag: string) => {
    apply(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <span className="jx-label">{label}</span>
      <JxTagInput
        ariaLabel={label}
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={add}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => remove(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

